CREATE TABLE ana_admin (id BIGINT AUTO_INCREMENT, first_name VARCHAR(255) NOT NULL, last_name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, username VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(id)) ENGINE = INNODB;
CREATE TABLE ana_browsers (id BIGINT AUTO_INCREMENT, match_word VARCHAR(255), browser_name VARCHAR(255) UNIQUE, PRIMARY KEY(id)) ENGINE = INNODB;
CREATE TABLE ana_devices (id BIGINT AUTO_INCREMENT, match_word VARCHAR(255), device_name VARCHAR(255) UNIQUE, PRIMARY KEY(id)) ENGINE = INNODB;
CREATE TABLE ana_item_analytics (id BIGINT AUTO_INCREMENT, id_item BIGINT NOT NULL, country_code VARCHAR(20), country_name VARCHAR(255), region_name VARCHAR(255), city_name VARCHAR(255), zipcode VARCHAR(255), latitude VARCHAR(50), longitude VARCHAR(50), ip_add VARCHAR(50), timezone VARCHAR(50), id_browser BIGINT, browser_version VARCHAR(255), id_platform BIGINT, id_device BIGINT, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX id_item_idx (id_item), INDEX id_browser_idx (id_browser), INDEX id_platform_idx (id_platform), INDEX id_device_idx (id_device), PRIMARY KEY(id)) ENGINE = INNODB;
CREATE TABLE ana_items (id BIGINT AUTO_INCREMENT, id_project BIGINT NOT NULL, url VARCHAR(255) UNIQUE, item_key VARCHAR(50) NOT NULL UNIQUE, status TINYINT(1) DEFAULT '1', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX id_project_idx (id_project), PRIMARY KEY(id)) ENGINE = INNODB;
CREATE TABLE ana_platforms (id BIGINT AUTO_INCREMENT, match_word VARCHAR(255), platform_name VARCHAR(255) UNIQUE, PRIMARY KEY(id)) ENGINE = INNODB;
CREATE TABLE ana_projects (id BIGINT AUTO_INCREMENT, id_user BIGINT NOT NULL, project_name VARCHAR(255) NOT NULL, description TEXT NOT NULL, url VARCHAR(255) NOT NULL, project_key VARCHAR(50) NOT NULL UNIQUE, status TINYINT(1) DEFAULT '0', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX id_user_idx (id_user), PRIMARY KEY(id)) ENGINE = INNODB;
CREATE TABLE ana_user_login (id BIGINT AUTO_INCREMENT, id_user BIGINT NOT NULL, ip_add VARCHAR(30), login_time DATETIME, INDEX id_user_idx (id_user), PRIMARY KEY(id)) ENGINE = INNODB;
CREATE TABLE ana_users (id BIGINT AUTO_INCREMENT, first_name VARCHAR(255) NOT NULL, last_name VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, username VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, address VARCHAR(255), user_type VARCHAR(255) DEFAULT 'user', status TINYINT(1) DEFAULT '0', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY(id)) ENGINE = INNODB;
ALTER TABLE ana_item_analytics ADD CONSTRAINT ana_item_analytics_id_platform_ana_platforms_id FOREIGN KEY (id_platform) REFERENCES ana_platforms(id) ON DELETE CASCADE;
ALTER TABLE ana_item_analytics ADD CONSTRAINT ana_item_analytics_id_item_ana_items_id FOREIGN KEY (id_item) REFERENCES ana_items(id) ON DELETE CASCADE;
ALTER TABLE ana_item_analytics ADD CONSTRAINT ana_item_analytics_id_device_ana_devices_id FOREIGN KEY (id_device) REFERENCES ana_devices(id) ON DELETE CASCADE;
ALTER TABLE ana_item_analytics ADD CONSTRAINT ana_item_analytics_id_browser_ana_browsers_id FOREIGN KEY (id_browser) REFERENCES ana_browsers(id) ON DELETE CASCADE;
ALTER TABLE ana_items ADD CONSTRAINT ana_items_id_project_ana_projects_id FOREIGN KEY (id_project) REFERENCES ana_projects(id) ON DELETE CASCADE;
ALTER TABLE ana_projects ADD CONSTRAINT ana_projects_id_user_ana_users_id FOREIGN KEY (id_user) REFERENCES ana_users(id) ON DELETE CASCADE;
ALTER TABLE ana_user_login ADD CONSTRAINT ana_user_login_id_user_ana_users_id FOREIGN KEY (id_user) REFERENCES ana_users(id) ON DELETE CASCADE;
